SELECT CASE WHEN amount >= 1550 THEN 'high' WHEN amount >= 650 THEN 'mid' ELSE 'low' END AS amount_bucket, MIN(amount) AS min_amount, AVG(amount) AS avg_amount, MIN(paid_at) AS first_paid_at FROM payments WHERE method IN ('cash', 'bank_transfer', 'paypal') OR TO_DATE(paid_at) >= '2023-12-01' GROUP BY CASE WHEN amount >= 1550 THEN 'high' WHEN amount >= 650 THEN 'mid' ELSE 'low' END
